const o={"roof-steam-cleaning":{heroDescription:"Professional roof steam cleaning and roof soft washing with safe moss and algae removal from roof tiles. Effective, environmentally friendly treatment that protects your roof and improves curb appeal across Central Scotland.",whyChoose:{title:"Why Choose Our Roof Steam Cleaning?",points:[{title:"Safe & Effective",description:"Our safe roof steam cleaning provides moss removal from roof and algae removal from roof tiles without damaging tiles or the environment. Professional roof cleaning and moss treatment for lasting protection."},{title:"Property Protection",description:"Regular roof cleaning prevents damage from organic growth and maintains your property's curb appeal and value."},{title:"Quick & Reliable",description:"Professional service completed efficiently with minimal disruption. We work around your schedule."}]},processSteps:[{title:"Book & get a quote",description:"Contact us to schedule your roof steam clean. We'll provide a free quote and a convenient date."},{title:"We come to you",description:"We bring our equipment to your property. Safe steam cleaning with no high pressure that could damage tiles."},{title:"Payment & completion",description:"Settle on completion. We'll leave your roof looking clean and protected."}],faqs:[{question:"How often should I have my roof cleaned?",answer:"Every 2–3 years is typical for moss and algae, depending on exposure and tree cover. We can advise after an inspection."},{question:"Is roof steam cleaning safe for all roof types?",answer:"Yes. We use low-pressure steam and appropriate treatments suitable for tiles, slates and most roof surfaces."},{question:"What's the difference between roof steam cleaning and roof soft washing?",answer:"They're closely related — both are low-pressure alternatives to jet washing. We use steam and soft-wash treatments together depending on the roof type, so you get the same damage-free result either way."},{question:"Do you treat the gutters too?",answer:"We can clear and clean gutters as part of the service or as a separate job. Ask for a quote."}]},"render-softwashing":{heroDescription:"Render, roughcast and pebbledash softwashing specialists: expert stain removal from render surfaces without damage. We bring render cleaning and softwash expertise to your property for a refreshed, clean finish.",whyChoose:{title:"Why Choose GlenView's Render & Roughcast Cleaning?",points:[{title:"15+ Years Experience",description:""},{title:"5 Star Rated",description:""},{title:"Scotland Wide Service",description:""},{title:"Free Quotes Available",description:""}]},processSteps:[{title:"Book & get a quote",description:"Tell us about your property and we'll provide a free quote for render softwashing."},{title:"We come to you",description:"We bring our softwash equipment and apply the right treatment for your render type."},{title:"Payment & completion",description:"Payment on completion. Your walls will look refreshed and clean."}],faqs:[{question:"How can I book or get a quote?",answer:"Call us on 07862 139959 or fill out the contact form on our website, and we'll get back to you with a free, no-obligation quote."},{question:"Do you offer ongoing maintenance?",answer:"Yes. Alongside a one-off render softwash, we offer a maintenance plan to keep your property looking its best year-round."},{question:"What's the difference between pressure washing and softwashing?",answer:"Pressure washing uses high-pressure water jets, which can chip paint, crack render and blast out mortar. Softwashing is a gentler, low-pressure treatment that's designed for render, roughcast, pebbledash and painted surfaces."},{question:"Do you clean roughcast and pebbledash as well as smooth render?",answer:"Yes — roughcast, pebbledash and smooth render all respond well to softwashing, though dwell time varies by coating age and texture."},{question:"How much does render softwashing cost?",answer:"Cost depends on your property's size, condition and render type. We offer a free, no-obligation quote so you know the exact price before any work begins."},{question:"Are you fully insured?",answer:"Yes. GlenView Exterior Cleaning is fully insured, and we're happy to provide details on request."},{question:"Do I need to be home during the clean?",answer:"No. As long as we can access the exterior of your property and a water supply, you don't need to be present."},{question:"Do you cover the whole of Scotland?",answer:"Yes, excluding the islands. We're based in Bishopbriggs and cover mainland Scotland."},{question:"Do you work with both homeowners and businesses?",answer:"Yes. We carry out render softwashing for homeowners as well as commercial properties, at your home or business."},{question:"What other services do you offer?",answer:"Alongside render softwashing, we also provide roof steam cleaning, driveway cleaning, gutter cleaning, PVC white cleaning and window cleaning."}]},"driveway-cleaning":{heroDescription:"Professional driveway cleaning and pressure washing to restore the look of your entrance. We remove dirt, moss and stains from block paving, concrete and other surfaces.",whyChoose:{title:"Why Choose Our Driveway Cleaning?",points:[{title:"Restored Appearance",description:"Pressure washing and cleaning bring driveways back to a clean, well-maintained look and can help prevent slip hazards from moss and algae."},{title:"All Surface Types",description:"We work on block paving, concrete, tarmac and other driveway surfaces with the right method for each."},{title:"Reliable Service",description:"We turn up when we say we will and complete the job to a high standard."}]},processSteps:[{title:"Book & get a quote",description:"Contact us with your driveway size and surface type for a free quote."},{title:"We come to you",description:"We bring our pressure washing and cleaning equipment to your property."},{title:"Payment & completion",description:"Pay on completion. Your driveway will look clean and refreshed."}],faqs:[{question:"Can you clean block paving?",answer:"Yes. We clean block paving, concrete, tarmac and other surfaces using appropriate pressure and methods."},{question:"How long does driveway cleaning take?",answer:"It depends on size and condition. We'll give you an estimate when you get a quote."}]},"gutter-cleaning":{heroDescription:"Gutter cleaning and gutter maintenance to keep drainage clear and protect your property. We clear leaves, debris and blockages, can inspect gutters for damage, and clean fascias and soffits while we're up there.",whyChoose:{title:"Why Choose Our Gutter Cleaning?",points:[{title:"Clear Drainage",description:"Blocked gutters can cause overflow, damp and damage to walls and foundations. Regular clearing keeps water flowing correctly."},{title:"Safe Access",description:"We work safely at height with appropriate equipment to clear and clean gutters without risking damage to your property."},{title:"Inspection Included",description:"We can highlight any damage or repairs needed so you can plan maintenance."}]},processSteps:[{title:"Book & get a quote",description:"Get in touch for a free quote. We'll need to know approximate property size and number of gutters."},{title:"We come to you",description:"We clear gutters by hand and with appropriate tools, and remove debris safely."},{title:"Payment & completion",description:"Payment on completion. Gutters will be clear and functioning properly."}],faqs:[{question:"How often should gutters be cleaned?",answer:"At least once a year, and more often if you have overhanging trees or heavy leaf fall."},{question:"Do you clean downpipes too?",answer:"We can clear downpipes as part of the service if required. Ask when booking."},{question:"Can you clean fascias and soffits at the same time?",answer:"Yes — since we're already working at gutter height, we can clean fascias and soffits in the same visit. Ask for a combined quote."}]},"pvc-white-cleaning":{heroDescription:"PVC white cleaning for fascias, soffits and gutters. We restore the bright appearance of white PVC and remove green algae, dirt and staining.",whyChoose:{title:"Why Choose Our PVC White Cleaning?",points:[{title:"Restored Brightness",description:"Green algae and dirt can make white PVC look dull. Our cleaning brings fascias, soffits and gutters back to a clean, bright finish."},{title:"Safe Methods",description:"We use methods and products that clean effectively without damaging PVC or seals."},{title:"Complete Exterior",description:"Often combined with gutter cleaning or window cleaning for a full exterior refresh."}]},processSteps:[{title:"Book & get a quote",description:"Contact us for a free quote. We'll need to know the extent of PVC (e.g. fascias, soffits, gutters)."},{title:"We come to you",description:"We clean PVC with appropriate products and equipment, working safely at height where needed."},{title:"Payment & completion",description:"Payment on completion. Your PVC will look clean and bright."}],faqs:[{question:"Will cleaning damage my PVC?",answer:"No. We use gentle, effective cleaning that is safe for PVC and won't damage seals or fixings."},{question:"How long do results last?",answer:"With normal exposure, PVC can stay looking good for 12–24 months before another clean is typically needed."}]},"window-cleaning":{heroDescription:"Professional window cleaning for residential and commercial properties. Streak-free, sparkling results and reliable scheduling.",whyChoose:{title:"Why Choose Our Window Cleaning?",points:[{title:"Streak-Free Finish",description:"We clean windows to a high standard so you get a clear, streak-free view and a smart appearance."},{title:"Regular or One-Off",description:"Book a one-off clean or set up a regular schedule that suits you."},{title:"Reliable & Insured",description:"We're fully insured and turn up when we say we will."}]},processSteps:[{title:"Book & get a quote",description:"Tell us how many windows and whether you want a one-off or regular service for a free quote."},{title:"We come to you",description:"We clean windows from the outside (and inside by arrangement) with the right tools and products."},{title:"Payment & completion",description:"Payment on completion or as agreed for regular customers."}],faqs:[{question:"Do you clean inside as well?",answer:"We can quote for inside and outside. Let us know when you get in touch."},{question:"How often should windows be cleaned?",answer:"Many customers choose every 4–8 weeks. We can suggest a frequency based on your property and preference."}]},"moss-removal":{heroDescription:"Specialist moss and algae removal for roofs, patios and driveways across Central Scotland. We clear moss safely from slate, tile and concrete without damaging the surface, and can apply a treatment to slow regrowth.",whyChoose:{title:"Why Choose GlenView's Moss & Algae Removal?",points:[{title:"Damage-Free Methods",description:"We use low-pressure removal suited to slate, concrete and clay tiles, avoiding the aggressive pressure-washing that can crack or dislodge them."},{title:"Treatment Included",description:"We can apply a moss and algae treatment after removal to slow regrowth, so the job lasts longer than a one-off clear."},{title:"Roofs, Patios & Driveways",description:"Moss and algae don't just build up on roofs — we clear it from patios and driveways too, where it makes surfaces slippery."}]},processSteps:[{title:"Book & get a quote",description:"Contact us for a free inspection and quote — we'll tell you how urgent the moss or algae build-up is."},{title:"We come to you",description:"We remove moss and algae by hand and low-pressure methods, then apply treatment where needed."},{title:"Payment & completion",description:"Payment on completion. We'll leave the surface clear and protected against regrowth."}],faqs:[{question:"How do I know if my roof needs moss removal?",answer:"Look for visible green or grey clumps along ridge lines and in roof valleys, granules collecting in your gutters, or damp patches appearing on ceilings after rain."},{question:"Will moss removal damage my roof tiles?",answer:"No — we use low-pressure methods suited to slate, concrete and clay tiles, and avoid aggressive pressure-washing that can crack or dislodge tiles."},{question:"Do you remove algae as well as moss?",answer:"Yes — algae causes the green staining you often see on roofs, patios and driveways, and we treat both together."},{question:"Do you offer moss removal near me?",answer:"Yes, we cover North Glasgow, East Dunbartonshire, Lanarkshire, Falkirk and Stirling. Get in touch for a free quote."}]},"patio-cleaning":{heroDescription:"Patio cleaning and pressure washing for slabs, monoblock and decking. We lift algae, moss and grime from patios across Central Scotland, leaving outdoor spaces safe and ready to use.",whyChoose:{title:"Why Choose GlenView's Patio Cleaning?",points:[{title:"Safer Underfoot",description:"Algae and moss on patios and monoblock get slippery fast — regular cleaning removes the hazard as well as the mess."},{title:"All Surface Types",description:"We clean slabs, monoblock, decking and natural stone patios with the right pressure and method for each."},{title:"Ready for Use",description:"A clean patio means your outdoor space is ready for the next barbecue or get-together, not just presentable."}]},processSteps:[{title:"Book & get a quote",description:"Contact us with your patio size and surface type for a free quote."},{title:"We come to you",description:"We bring our pressure washing equipment and clean the full patio area, including joints and edges."},{title:"Payment & completion",description:"Pay on completion. Your patio will look clean and be safer to walk on."}],faqs:[{question:"Can you clean monoblock patios?",answer:"Yes — we clean monoblock, slabs, natural stone and decking, adjusting pressure to suit each surface."},{question:"Will pressure washing damage patio joints?",answer:"No, we use appropriate pressure and technique so jointing sand and pointing aren't stripped out."},{question:"Do you offer patio cleaning near me?",answer:"Yes, we cover North Glasgow, East Dunbartonshire, Lanarkshire, Falkirk and Stirling. Get in touch for a free quote."}]}};function t(e){return o[e]}export{t as g};
